/deep/.ivu-drawer-close{
  right: 30px;
}
.iview-video-style {
  width: 40%;
  height: 180px;
  border-radius: 10px;
  background-color: #707070;
  position: relative;
  overflow: hidden;
  .video-style{
    width: 100%;
    height: 100%;
  }
}

.iview-video-style .iconv {
  color: #fff;
  line-height: 180px;
  width: 50px;
  height: 50px;
  display: inherit;
  font-size: 26px;
  position: absolute;
  top: -74px;
  left: 50%;
  margin-left: -25px;
}

.iview-video-style .mark {
  position: absolute;
  width: 100%;
  height: 30px;
  top: 0;
  background-color: rgba(0, 0, 0, 0.5);
  text-align: center;
}
.ivu-mt{
  margin: 0 auto!important;
}
.header {
  display: flex;
  align-items: center;
  padding: 30px 0 25px 25px;
  font-size: 13px;
  color: #606266;

  .iconfont {
    margin-right: 12px;
    color: #2D8CF0;
  }

  .title {
    font-weight: 500;
    font-size: 16px;
    color: #000000;
  }
}

.ivu-tabs {
  >>>.ivu-tabs-bar {
    border-bottom: 0;
    margin-bottom: 30px;
    background-color: #F5F7FA;
  }

  >>>.ivu-tabs-tab {
    height: 40px;
    padding: 0 20px;
    font-size: 13px;
    line-height: 40px;
    color: #000000;

    &:hover {
      color: #000000 !important;
    }
  }

  >>>.ivu-tabs-tab-active {
    background-color: #FFFFFF;
  }

  >>>.ivu-tabs-ink-bar {
    top: 0;
    bottom: auto;
  }

  .ivu-tabs-tabpane {
    padding: 0 24px;
  }
}

.ivu-form {
  >>>.ivu-form-item-label {
    padding: 10px 6px 10px 0;
  }
}

>>>.pictrue {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 60px;
  border: 1px dotted rgba(0, 0, 0, 0.1);
  margin: 0 15px 10px 0;
  cursor: pointer;

  img {
    width: 100%;
    height: 100%;
  }

  .btndel {
    position: absolute;
    top: -4px;
    left: 46px;
    width: 20px;
    height: 20px;
    z-index: 1;
  }
}

>>>.upLoad {
  width: 58px;
  height: 58px;
  border: 1px dotted rgba(0, 0, 0, 0.1);
  border-radius: 4px;
  background-color: rgba(0, 0, 0, 0.02);
  line-height: 58px;
  cursor: pointer;
}

.input-display {
  display: none;
}

.ifam {
  width: 344px;
  height: 644px;
  background: url('../../../assets/images/phonebg.png') no-repeat center top;
  background-size: 344px 644px;
  padding: 40px 20px;
  padding-top: 50px;

  .content {
    height: 560px;
    overflow: hidden;
    scrollbar-width: none; /* firefox */
    -ms-overflow-style: none; /* IE 10+ */
    overflow-x: hidden;
    overflow-y: auto;
  }
}

.videbox {
  width: 60px;
  height: 60px;
  background: rgba(0, 0, 0, 0.02);
  border-radius: 4px;
  border: 1px dashed #ddd;
  line-height: 50px;
  text-align: center;
  color: #898989;
  font-size: 30px;
  font-weight: 400;
  cursor: pointer;
}
.drawer-footer {
  position fixed
  right 0
  bottom 0
  z-index 2
  width 1000px
  padding 13px
  border-top 1px solid #EEEEEE
  background-color #FFFFFF
  text-align center
}
.labelInput{
    position: relative;
    border: 1px solid #dcdee2;
    width: 50%;
    border-radius: 4px;
    min-height: 32px;
    padding-right: 24px;
    padding-left: 8px;
    cursor: pointer;

    >div{
      flex: 1;
      min-height: 30px;
      padding-right: 24px;
      padding-left: 8px;
      font-size: 0;
      line-height: 30px;

      .span {
        vertical-align: middle;
        font-size: 12px;
        color: #c5c8ce;
      }
    }

    .ivu-icon {
      position: absolute;
      top: 50%;
      right: 8px;
      transform: translateY(-50%);
      font-size: 14px;
      line-height: 1;
      color: #808695;
    }
}
.color-list .color-item{
  width: 70px;
  height: 28px;
  line-height: 28px;
  color: #fff;
  margin-right: 10px;
  border-radius: 2px;
  text-align: center;
}
.color-list .color-item.colorBlue{
  background: linear-gradient(270deg, #5ecfff 0%, #0084ff 100%);
}
.color-list .color-item .num{
  color: #1890ff;
    width: 14px;
    height: 14px;
    text-align: center;
    line-height: 14px;
    border-radius: 50%;
    background-color: #fff;
    margin-right: 6px;
}
.addCustom_content{
  margin-top: 20px;
}
.addCustom_content .custom_box{
  margin-bottom: 10px;
}
.custom-input{
  width: 100px;
    margin-right: 10px;
}
.ivu-checkbox-wrapper{
  margin-right: 19px;
}
.addCustom_content .addfont{
  display: inline-block;
  font-size: 13px;
  font-weight: 400;
  color: #1890ff;
  cursor: pointer;
}
.select-add{
  width: 200px;
    margin-left: 6px;
    margin-right: 10px;
}
.addCustomBox{
  margin-top: 12px;
  font-size: 13px;
  font-weight: 400;
  color: #1890ff;
}
.addCustomBox .btn{
  cursor: pointer;
    width: max-content;
}
.addCustomBox .tips{
  display: inline-bolck;
    font-size: 12px;
    font-weight: 400;
    color: #999;
    margin-top: 14px;
}
>>>.wang-editor {
  margin-left: 20px;
